#!/usr/bin/env -S uv run
# /// script
# requires-python = ">=3.10"
# dependencies = ["pyyaml>=6"]
# ///
"""Vendor zlib in-tree at a pinned commit.

shaped-core builds offline and reproducibly, so third-party dependencies live
in-tree rather than as submodules or fetched-at-configure-time packages. zlib
backs the Deflate third of cc::compress / cc::decompress (see the
SC_USE_VENDORED_ZLIB option in extern/CMakeLists.txt). This script regenerates
the vendored copy from a pinned upstream commit: it shallow-clones the tag into
a transient `.clone/` dir, asserts the tag resolves to the pinned hash (the hash
is the authority; the tag is a human-readable convenience), copies the minimal
subset we actually build, and deletes the clone.

Deflate is here for interoperability rather than for throughput -- it is what
reads a zip, a gzip or a PNG stream, while zstd and lz4 already own the ratio
and speed axes. That is why zlib is vendored over the faster zlib-ng: zlib needs
no generated config and no per-architecture SIMD detection, so it compiles
unchanged on every target we support, which is worth more here than a codec we
do not put on a hot path being two to four times faster.

Upstream keeps its sources flat at the repository root, and we split them into
include/ + src/ to match the lz4 and mimalloc layout. Only zlib.h and zconf.h
land in include/, which is exactly the public API; every internal header stays
in src/ where nothing outside can name it. zconf.h is committed upstream rather
than generated by configure, so the vendored copy needs no build-time step.

What is dropped, and why:
  gz*.c     -- the stdio gzFile layer, superseded here by cc::read_stream
  infback.c -- the callback-driven inflateBack API, which nothing calls
  contrib/, test/, examples/, doc/ -- not built
  configure, Makefile*, CMakeLists.txt, zconf.h.in, *.pc.in, zlib.map -- build machinery we replace
  amiga/, msdos/, nintendods/, old/, os400/, qnx/, watcom/, win32/ -- ports for platforms we do not target

gzguts.h is the one piece of that layer we keep, and not by preference: zutil.c
includes it unconditionally under `#ifndef Z_SOLO`, for the allocator
declarations its zcalloc/zfree need. It is a header, so keeping it costs one
file and pulls in no gz code -- the gz* prototypes stay declared and undefined,
which is harmless because nothing here references them and they never reach the
link. Z_SOLO itself is deliberately NOT defined: it would also strip
compress()/uncompress() and force a caller-supplied allocator on us.

Re-running is idempotent: the previously vendored files are wiped first, so
files dropped upstream do not linger. The vendored payload (include/, src/,
LICENSE) is committed to the repo; this script is only needed to bump or re-vet
the version.
"""

import os
import shutil
import stat
import subprocess
import sys
from pathlib import Path

# This script lives in extern/zlib/ and vendors alongside itself.
DEST = Path(__file__).resolve().parent
CLONE = DEST / ".clone"

# The pin lives in dependency.yml next to this script, so it is written once.
# The tag is for humans; pin_hash is the authority — the clone is rejected unless the tag resolves to exactly that commit.
sys.path.insert(0, str(DEST.parent))
import deps_manifest  # noqa: E402

# Upstream-relative source -> vendored destination (relative to DEST).
# The internal headers reach zlib.h with a quote include, which misses in src/ and then resolves against
# include/ off the target's include path — the same arrangement extern/lz4/ uses.
COPY_MAP = {
    "zlib.h": "include/zlib.h",
    "zconf.h": "include/zconf.h",
    "adler32.c": "src/adler32.c",
    "compress.c": "src/compress.c",
    "crc32.c": "src/crc32.c",
    "crc32.h": "src/crc32.h",
    "deflate.c": "src/deflate.c",
    "deflate.h": "src/deflate.h",
    # Not the gz layer, but zutil.c includes it for the allocator declarations — see the module docstring.
    "gzguts.h": "src/gzguts.h",
    "inffast.c": "src/inffast.c",
    "inffast.h": "src/inffast.h",
    "inffixed.h": "src/inffixed.h",
    "inflate.c": "src/inflate.c",
    "inflate.h": "src/inflate.h",
    "inftrees.c": "src/inftrees.c",
    "inftrees.h": "src/inftrees.h",
    "trees.c": "src/trees.c",
    "trees.h": "src/trees.h",
    "uncompr.c": "src/uncompr.c",
    "zutil.c": "src/zutil.c",
    "zutil.h": "src/zutil.h",
    "LICENSE": "LICENSE",
}

# Everything we own under DEST that a re-vendor must wipe first (so a file dropped
# upstream does not linger). The script, CMakeLists.txt, and this list itself stay.
WIPE = ["include", "src", "LICENSE"]


def _force_rmtree(path: Path) -> None:
    """rmtree that survives Windows: git packs the .git objects read-only, which
    blocks os.unlink — clear the read-only bit on error and retry."""

    def on_error(func, p, _exc):
        os.chmod(p, stat.S_IWRITE)
        func(p)

    shutil.rmtree(path, onexc=on_error)


def run(*args: str, cwd: Path | None = None) -> str:
    """Run a git command, returning stripped stdout; abort loudly on failure."""
    result = subprocess.run(args, cwd=cwd, capture_output=True, text=True)
    if result.returncode != 0:
        sys.exit(f"command failed: {' '.join(args)}\n{result.stderr.strip()}")
    return result.stdout.strip()


def main() -> int:
    up = deps_manifest.one(DEST)

    # Clean slate: a stale clone or partial previous run must not leak in.
    if CLONE.exists():
        _force_rmtree(CLONE)
    CLONE.parent.mkdir(parents=True, exist_ok=True)

    # Shallow-clone just the pinned tag, then verify it is the pinned commit.
    print(f"cloning {up.repo} @ {up.tag} ...")
    run("git", "clone", "--depth", "1", "--branch", up.tag, up.repo, str(CLONE))
    head = run("git", "-C", str(CLONE), "rev-parse", "HEAD")
    if head != up.pin_hash:
        _force_rmtree(CLONE)
        sys.exit(
            f"pin mismatch: tag {up.tag} resolved to {head}, expected {up.pin_hash}.\n"
            "Update tag and pin_hash together in dependency.yml, after vetting the new commit."
        )

    # Wipe the previously vendored payload so dropped-upstream files do not linger.
    for name in WIPE:
        target = DEST / name
        if target.is_dir():
            shutil.rmtree(target)
        elif target.exists():
            target.unlink()

    # Copy the minimal subset we build.
    for src, dst in COPY_MAP.items():
        dest_path = DEST / dst
        dest_path.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(CLONE / src, dest_path)

    _force_rmtree(CLONE)

    vendored = sorted(
        p.relative_to(DEST).as_posix()
        for p in DEST.rglob("*")
        if p.is_file() and ".clone" not in p.parts
    )

    print(f"\nvendored {up.name} {up.tag} ({up.pin_hash[:12]}): {len(vendored)} files")
    print(f"into {DEST.as_posix()}")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
